#!/usr/bin/env node
// @ts-check
// Generates THIRD_PARTY_NOTICES.md from package-lock.json plus each installed package's licence
// file. Do not edit THIRD_PARTY_NOTICES.md by hand: run `node scripts/third-party-notices.js`.
//
// The output is the same on every platform. npm installs only the keychain binary for the current
// OS, so platform-specific packages (lockfile `os`/`cpu`) are listed from the lockfile alone, and
// their licence text is not read from disk.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'THIRD_PARTY_NOTICES.md');

/** @param {string} dir @returns {string|null} licence text of an installed package */
function licenceText(dir) {
  if (!existsSync(dir)) return null;
  const names = readdirSync(dir).filter((f) => /^(licen[cs]e|copying|unlicense)(\.|-|$)/i.test(f)).sort();
  // Prefer the plain LICENSE file over LICENSE-MIT style variants.
  const pick = names.find((f) => /^licen[cs]e(\.(md|txt))?$/i.test(f)) ?? names[0];
  return pick ? readFileSync(join(dir, pick), 'utf8').replace(/\r\n/g, '\n').trim() : null;
}

/** @param {string|null} text @param {any} pkgJson */
function copyrightLine(text, pkgJson) {
  const line = text?.split('\n').map((s) => s.trim()).find((s) => /^(copyright\b|\(c\)|©)/i.test(s) && /\d{4}|[a-z]{3}/i.test(s.replace(/^copyright/i, '')));
  if (line) return line;
  const a = pkgJson?.author;
  const author = typeof a === 'string' ? a : a?.name;
  return author ? `Author: ${author.replace(/\s*<[^>]*>/, '').replace(/\s*\([^)]*\)/, '')}` : '(no copyright line in the package)';
}

/** Licence text with copyright lines removed, for grouping identical texts. @param {string} t */
const body = (t) => t.split('\n').filter((s) => !/^\s*(copyright\b|\(c\)|©)/i.test(s)).join('\n').replace(/\n{3,}/g, '\n\n').trim();

export function generate() {
  const lock = JSON.parse(readFileSync(join(ROOT, 'package-lock.json'), 'utf8'));
  /** @typedef {{ name: string, version: string, license: string, copyright: string, platform: boolean, parent: string, text: string|null }} Row */
  /** @type {Row[]} shipped: installed next to Ontologizer */
  const rows = [];
  /** @type {Row[]} build tools: development dependencies, never shipped or bundled */
  const devRows = [];
  const nameOf = (/** @type {string} */ path, /** @type {any} */ meta) => meta.name ?? path.slice(path.lastIndexOf('node_modules/') + 'node_modules/'.length);
  /** The package that lists a platform binary as an optional dependency (its real parent). @param {string} name */
  const parentOf = (name) => {
    for (const [path, meta] of Object.entries(lock.packages)) {
      if (path && meta.optionalDependencies && name in meta.optionalDependencies) return nameOf(path, meta);
    }
    return '(unknown parent package)';
  };
  for (const [path, meta] of Object.entries(lock.packages)) {
    if (!path) continue;
    const name = nameOf(path, meta);
    const platform = Boolean(meta.os || meta.cpu);
    const parent = platform ? parentOf(name) : '';
    const dir = join(ROOT, path);
    const pkgJson = !platform && existsSync(join(dir, 'package.json')) ? JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')) : null;
    const text = platform ? null : licenceText(dir);
    (meta.dev ? devRows : rows).push({
      name, version: meta.version, license: meta.license ?? 'UNKNOWN',
      copyright: platform ? `(platform-specific prebuilt binary of ${parent}; same project and licence)` : copyrightLine(text, pkgJson),
      platform, parent, text,
    });
  }
  const byName = (/** @type {Row} */ a, /** @type {Row} */ b) => a.name.localeCompare(b.name) || a.version.localeCompare(b.version);
  rows.sort(byName);
  devRows.sort(byName);

  const esc = (/** @type {string} */ s) => s.replace(/\|/g, '\\|');
  const out = [];
  out.push('# Third-party notices', '');
  out.push('<!-- GENERATED by scripts/third-party-notices.js from package-lock.json. Do not edit by hand. -->', '');
  out.push('Ontologizer is licensed under the MIT License (see `LICENSE`). It depends on the open-source packages below.', '');
  out.push('- **Bundled into exports:** `web/dist/embed.js` copies the d3 code it uses, and `web/dist/embed-3d.js` also `three`, into one file that `ontologizer export --format html` or `embed` puts inside every exported page. Each bundle starts with the full licence text and copyright line of every package it includes.');
  out.push('- **Served to your browser:** the local web page that `ontologizer` opens serves the d3 packages and `three` to your browser straight from `node_modules`.');
  out.push('- **Platform binaries:** `@napi-rs/keyring` ships one prebuilt binary per platform; npm installs only the one for your system.', '');
  /** @param {Row[]} list */
  const tally = (list) => {
    /** @type {Record<string, number>} */
    const counts = {};
    for (const r of list) counts[r.license] = (counts[r.license] || 0) + 1;
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ');
  };
  const devNote = devRows.length ? ` Plus ${devRows.length} build-only packages (${tally(devRows)}), listed under Build tools at the end: never shipped.` : '';
  out.push(`${rows.length} shipped packages: ${tally(rows)}.${devNote}`, '');
  out.push('## Packages', '');
  out.push('| Package | Version | Licence | Copyright |', '|---|---|---|---|');
  for (const r of rows) out.push(`| ${esc(r.name)} | ${r.version} | ${r.license} | ${esc(r.copyright)} |`);
  out.push('', '## Licence texts', '');
  out.push('Each distinct licence text appears once, with the packages that use it. Copyright lines are in the table above.', '');
  for (const lic of [...new Set(rows.map((r) => r.license))].sort()) {
    out.push(`### ${lic}`, '');
    /** @type {Map<string, { text: string, names: string[] }>} */
    const groups = new Map();
    for (const r of rows.filter((x) => x.license === lic && x.text)) {
      const key = body(/** @type {string} */ (r.text));
      if (!groups.has(key)) groups.set(key, { text: key, names: [] });
      groups.get(key)?.names.push(`${r.name}@${r.version}`);
    }
    const missing = rows.filter((x) => x.license === lic && !x.text && !x.platform);
    for (const g of groups.values()) {
      out.push(`Used by: ${g.names.join(', ')}`, '', '```text', g.text, '```', '');
    }
    if (missing.length) out.push(`No licence file shipped by: ${missing.map((r) => `${r.name}@${r.version}`).join(', ')}. Their \`package.json\` declares ${lic}.`, '');
    const plat = rows.filter((x) => x.license === lic && x.platform);
    if (plat.length) out.push(`Platform binaries under this licence (text as for ${[...new Set(plat.map((r) => r.parent))].join(', ')} above): ${plat.map((r) => r.name).join(', ')}.`, '');
  }
  if (devRows.length) {
    out.push('## Build tools: installed for development only, never shipped or bundled', '');
    out.push('These are development dependencies. They build `web/dist/` from source and are not part of the published package or of any exported page.', '');
    out.push('| Package | Version | Licence | Copyright |', '|---|---|---|---|');
    for (const r of devRows) out.push(`| ${esc(r.name)} | ${r.version} | ${r.license} | ${esc(r.copyright)} |`);
    out.push('');
  }
  return out.join('\n').replace(/\n+$/, '\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(OUT, generate());
  console.log(`wrote ${OUT}`);
}
